// WP-4.4 FSR 3.1 frame generation on Vulkan / render graph v2: see include/fuse/renderer/framegen/fg_gpu.hpp.
#include <fuse/renderer/framegen/fg_gpu.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cmath>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>
#endif

// Generated by cmake/rp_wp44.cmake: kFg<Pass>Spv (vendored GLSL passes), the FUSE passes and the FUSE_FG_* macros.
#include "fg_spv.h"

namespace fuse::renderer::framegen {

namespace {
// VkFormat values.
constexpr u32 kR8Uint = 13u, kR8G8Unorm = 16u, kR16G16Sint = 82u, kR16G16Sfloat = 83u, kR16G16B16A16Sfloat = 97u,
              kR32Uint = 98u, kR32Sfloat = 100u, kR32G32Sfloat = 103u;

template <usize N>
[[maybe_unused]] FgKernelCode code(const u32 (&spv)[N], const char* language) {
    return FgKernelCode{spv, sizeof(spv), language};
}

/// Occurrences of a pass in one frame's plan (descriptor sets per frame-in-flight slot).
[[maybe_unused]] u32 occurrencesOf(FgPass pass) {
    switch (pass) {
    case FgPass::OfSearch:
    case FgPass::OfSearchPortable:
    case FgPass::OfFilter: return kFgOfLevels;
    case FgPass::OfScale: return kFgOfLevels - 1u;
    case FgPass::UiComposite: return 2u;
    default: return 1u;
    }
}
} // namespace

FgKernelCode fg_kernel_code(FgPass pass, FgKernelLanguage language) {
    switch (pass) {
    case FgPass::Convert:
#if defined(FUSE_FG_CONVERT_SLANG)
        if (language == FgKernelLanguage::Auto || language == FgKernelLanguage::Slang) {
            return code(kFgConvertSlangSpv, "slang");
        }
#endif
#if defined(FUSE_FG_CONVERT_GLSL)
        if (language == FgKernelLanguage::Auto || language == FgKernelLanguage::Glsl) {
            return code(kFgConvertGlslSpv, "glsl");
        }
#endif
        break;
    case FgPass::UiComposite:
#if defined(FUSE_FG_COMPOSITE_SLANG)
        if (language == FgKernelLanguage::Auto || language == FgKernelLanguage::Slang) {
            return code(kFgCompositeSlangSpv, "slang");
        }
#endif
#if defined(FUSE_FG_COMPOSITE_GLSL)
        if (language == FgKernelLanguage::Auto || language == FgKernelLanguage::Glsl) {
            return code(kFgCompositeGlslSpv, "glsl");
        }
#endif
        break;
#if defined(FUSE_FG_SEARCH_PORTABLE)
    case FgPass::OfSearchPortable: return code(kFgOfSearchPortableSpv, "glsl");
#endif
#if defined(FUSE_FG_PASSES)
    case FgPass::OfPrepareLuma: return code(kFgOfPrepareLumaSpv, "glsl");
    case FgPass::OfLuminancePyramid: return code(kFgOfLuminancePyramidSpv, "glsl");
    case FgPass::OfScdHistogram: return code(kFgOfScdHistogramSpv, "glsl");
    case FgPass::OfScdDivergence: return code(kFgOfScdDivergenceSpv, "glsl");
    case FgPass::OfSearch: return code(kFgOfSearchSpv, "glsl");
    case FgPass::OfFilter: return code(kFgOfFilterSpv, "glsl");
    case FgPass::OfScale: return code(kFgOfScaleSpv, "glsl");
    case FgPass::FiReconstructAndDilate: return code(kFgFiReconstructAndDilateSpv, "glsl");
    case FgPass::FiSetup: return code(kFgFiSetupSpv, "glsl");
    case FgPass::FiReconstructPrevDepth: return code(kFgFiReconstructPrevDepthSpv, "glsl");
    case FgPass::FiGameMotionVectorField: return code(kFgFiGameMotionVectorFieldSpv, "glsl");
    case FgPass::FiGameVectorFieldInpaintingPyramid: return code(kFgFiGameVectorFieldInpaintingPyramidSpv, "glsl");
    case FgPass::FiOpticalFlowVectorField: return code(kFgFiOpticalFlowVectorFieldSpv, "glsl");
    case FgPass::FiDisocclusionMask: return code(kFgFiDisocclusionMaskSpv, "glsl");
    case FgPass::FiInterpolation: return code(kFgFiInterpolationSpv, "glsl");
    case FgPass::FiInpaintingPyramid: return code(kFgFiInpaintingPyramidSpv, "glsl");
    case FgPass::FiInpainting: return code(kFgFiInpaintingSpv, "glsl");
#endif
    default:
        break;
    }
    (void)language;
    return FgKernelCode{};
}

FgCapabilities queryFgCapabilities(const VulkanDevice* device, u32 sourceFormat) {
    FgCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    for (u32 p = 0; p < kFgPassCount; ++p) {
        if (fg_kernel_code(static_cast<FgPass>(p)).words == nullptr) {
            c.reason = "frame-generation passes not built (glslangValidator missing)";
            return c;
        }
    }
    const VkPhysicalDevice pd = static_cast<VkPhysicalDevice>(device->nativePhysicalDevice());
    VkPhysicalDeviceVulkan13Properties p13{};
    p13.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_1_3_PROPERTIES;
    VkPhysicalDeviceSubgroupProperties subgroup{};
    subgroup.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_PROPERTIES;
    subgroup.pNext = &p13;
    VkPhysicalDeviceProperties2 props2{};
    props2.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2;
    props2.pNext = &subgroup;
    vkGetPhysicalDeviceProperties2(pd, &props2);
    if (device->info().apiVersion < VK_API_VERSION_1_3) {
        c.reason = "Vulkan 1.3 required";
        return c;
    }
    if ((subgroup.supportedStages & VK_SHADER_STAGE_COMPUTE_BIT) == 0u ||
        (subgroup.supportedOperations & VK_SUBGROUP_FEATURE_QUAD_BIT) == 0u) {
        c.reason = "compute subgroup quad operations missing (SPD pyramids)";
        return c;
    }
    c.subgroupMin = p13.minSubgroupSize != 0u ? p13.minSubgroupSize : subgroup.subgroupSize;
    c.subgroupMax = p13.maxSubgroupSize != 0u ? p13.maxSubgroupSize : subgroup.subgroupSize;
    c.vendoredSearch = c.subgroupMin == c.subgroupMax && (c.subgroupMin == 32u || c.subgroupMin == 64u) &&
                       (subgroup.supportedOperations & VK_SUBGROUP_FEATURE_ARITHMETIC_BIT) != 0u;
    const u32 storage[] = {kR8Uint, kR8G8Unorm, kR16G16Sint, kR16G16Sfloat, kR16G16B16A16Sfloat, kR32Uint, kR32Sfloat, kR32G32Sfloat};
    for (const u32 f : storage) {
        VkFormatProperties fp{};
        vkGetPhysicalDeviceFormatProperties(pd, static_cast<VkFormat>(f), &fp);
        const VkFormatFeatureFlags need = VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT | VK_FORMAT_FEATURE_SAMPLED_IMAGE_BIT |
                                          VK_FORMAT_FEATURE_TRANSFER_DST_BIT | VK_FORMAT_FEATURE_TRANSFER_SRC_BIT;
        if ((fp.optimalTilingFeatures & need) != need) {
            c.reason = "a storage format of the frame-generation resources is unsupported";
            return c;
        }
    }
    {
        VkFormatProperties fp{};
        vkGetPhysicalDeviceFormatProperties(pd, static_cast<VkFormat>(sourceFormat), &fp);
        const VkFormatFeatureFlags need = VK_FORMAT_FEATURE_SAMPLED_IMAGE_BIT | VK_FORMAT_FEATURE_TRANSFER_DST_BIT |
                                          VK_FORMAT_FEATURE_TRANSFER_SRC_BIT;
        if ((fp.optimalTilingFeatures & need) != need) {
            c.reason = "source format not sampleable / copyable";
            return c;
        }
    }
    VkFormatProperties3 fp3{};
    fp3.sType = VK_STRUCTURE_TYPE_FORMAT_PROPERTIES_3;
    VkFormatProperties2 fp2{};
    fp2.sType = VK_STRUCTURE_TYPE_FORMAT_PROPERTIES_2;
    fp2.pNext = &fp3;
    vkGetPhysicalDeviceFormatProperties2(pd, static_cast<VkFormat>(kR16G16B16A16Sfloat), &fp2);
    const VkFormatFeatureFlags2 withoutFormat =
        VK_FORMAT_FEATURE_2_STORAGE_WRITE_WITHOUT_FORMAT_BIT | VK_FORMAT_FEATURE_2_STORAGE_READ_WITHOUT_FORMAT_BIT;
    if ((fp3.optimalTilingFeatures & withoutFormat) != withoutFormat) {
        // rw_output is declared without a format and the inpainting pass reads it (Vulkan 1.3 per-format features).
        c.reason = "RGBA16F storage read / write without format unsupported";
        return c;
    }
    c.supported = true;
    c.reason = "ok";
#else
    (void)device;
    (void)sourceFormat;
    c.reason = "stub backend";
#endif
    return c;
}

FrameGenGpu::~FrameGenGpu() { destroy(); }

bool FrameGenGpu::init(const FgGpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.framesInFlight == 0u || desc.framesInFlight > kMaxSlots) {
        return false;
    }
    const FgCapabilities caps = queryFgCapabilities(desc.device, desc.sourceFormat);
    if (!caps.supported) {
        return false;
    }
    bool portable = true;
    switch (desc.search) {
    case FgSearchVariant::Vendored:
        if (!caps.vendoredSearch) {
            return false;
        }
        portable = false;
        break;
    case FgSearchVariant::Portable: portable = true; break;
    case FgSearchVariant::Auto:
    default: portable = !caps.vendoredSearch; break;
    }
    if (!fg_init_state(m_host, desc.displayWidth, desc.displayHeight, desc.maxRenderWidth, desc.maxRenderHeight, portable)) {
        return false;
    }
    const FgKernelCode convert = fg_kernel_code(FgPass::Convert, desc.language);
    const FgKernelCode composite = fg_kernel_code(FgPass::UiComposite, desc.language);
    if (convert.words == nullptr || composite.words == nullptr || std::strcmp(convert.language, composite.language) != 0) {
        return false;
    }
    m_initialized = true; // destroy() releases partial state from here on
    m_language = convert.language;
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kFgCbSlotBytes;
    ring.usage = BufferUsage::Uniform;
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "fg.constants";
    if (!m_desc.allocator->createBuffer(ring, m_ring) || m_ring.mapped == nullptr || !createPipelines() || !createResources()) {
        destroy();
        return false;
    }
    return true;
#else
    return false;
#endif
}

void FrameGenGpu::destroy() {
    if (!m_initialized) {
        return;
    }
    destroyResources();
    destroyPipelines();
    if (m_ring.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_ring);
    }
    m_ring = Buffer{};
    m_host = FgHostState{};
    m_setup = FgFrameSetup{};
    m_begun = false;
    m_forceReset = false;
    m_language = "none";
    m_stats = FgGpuStats{};
    m_initialized = false;
}

bool FrameGenGpu::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    const VkDevice vk = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (u32 i = 0; i < 2u; ++i) {
        VkSamplerCreateInfo s{};
        s.sType = VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO;
        s.magFilter = i == 0u ? VK_FILTER_NEAREST : VK_FILTER_LINEAR;
        s.minFilter = s.magFilter;
        s.mipmapMode = i == 0u ? VK_SAMPLER_MIPMAP_MODE_NEAREST : VK_SAMPLER_MIPMAP_MODE_LINEAR;
        s.addressModeU = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        s.addressModeV = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        s.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        s.maxLod = VK_LOD_CLAMP_NONE;
        VkSampler sampler = VK_NULL_HANDLE;
        if (vkCreateSampler(vk, &s, nullptr, &sampler) != VK_SUCCESS) {
            return false;
        }
        m_samplers[i] = sampler;
    }
    u32 poolCounts[8] = {};
    u32 setCount = 0;
    for (u32 p = 0; p < kFgPassCount; ++p) {
        const FgPass pass = static_cast<FgPass>(p);
        if ((pass == FgPass::OfSearch && m_host.portableSearch) || (pass == FgPass::OfSearchPortable && !m_host.portableSearch)) {
            continue; // the unused search variant is not created
        }
        PassPipeline& pp = m_passes[p];
        pp.occurrences = occurrencesOf(pass);
        const FgKernelCode kc = fg_kernel_code(pass, m_desc.language);
        if (kc.words == nullptr || !fsr3::reflect_spirv(kc.words, kc.bytes / 4u, pp.reflection)) {
            return false;
        }
        VkDescriptorSetLayoutBinding lb[kMaxBindings]{};
        VkSampler immutable[kMaxBindings]{};
        pp.bindingCount = 0;
        for (const fsr3::SpirvBinding& b : pp.reflection.bindings) {
            FgBindingTarget target{};
            if (b.set != 0u || pp.bindingCount >= kMaxBindings || !fg_resolve_binding(b.name.c_str(), fg_pass_is_optical_flow(pass), target)) {
                return false; // the vendored pass and the host's name tables disagree
            }
            VkDescriptorType type = VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE;
            switch (b.kind) {
            case fsr3::SpirvDescriptorKind::SampledImage: type = VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE; break;
            case fsr3::SpirvDescriptorKind::StorageImage: type = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE; break;
            case fsr3::SpirvDescriptorKind::Sampler: type = VK_DESCRIPTOR_TYPE_SAMPLER; break;
            case fsr3::SpirvDescriptorKind::UniformBuffer: type = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER; break;
            case fsr3::SpirvDescriptorKind::StorageBuffer: type = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; break;
            default: return false;
            }
            const bool kindOk = (target.kind == FgBindingKind::Sampled && type == VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE) ||
                                (target.kind == FgBindingKind::Storage && type == VK_DESCRIPTOR_TYPE_STORAGE_IMAGE) ||
                                (target.kind == FgBindingKind::Sampler && type == VK_DESCRIPTOR_TYPE_SAMPLER) ||
                                (target.kind == FgBindingKind::Uniform && type == VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER) ||
                                (target.kind == FgBindingKind::StorageBuffer && type == VK_DESCRIPTOR_TYPE_STORAGE_BUFFER);
            if (!kindOk) {
                return false;
            }
            const u32 i = pp.bindingCount++;
            pp.bindings[i].binding = b.binding;
            pp.bindings[i].descriptorType = static_cast<u32>(type);
            pp.bindings[i].target = target;
            lb[i].binding = b.binding;
            lb[i].descriptorType = type;
            lb[i].descriptorCount = 1;
            lb[i].stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
            if (type == VK_DESCRIPTOR_TYPE_SAMPLER) {
                immutable[i] = static_cast<VkSampler>(m_samplers[target.resource == FgResource::SamplerPoint ? 0 : 1]);
                lb[i].pImmutableSamplers = &immutable[i];
            }
            poolCounts[static_cast<u32>(type)] += m_desc.framesInFlight * pp.occurrences;
        }
        setCount += m_desc.framesInFlight * pp.occurrences;
        VkDescriptorSetLayoutCreateInfo sl{};
        sl.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
        sl.bindingCount = pp.bindingCount;
        sl.pBindings = lb;
        VkDescriptorSetLayout setLayout = VK_NULL_HANDLE;
        if (vkCreateDescriptorSetLayout(vk, &sl, nullptr, &setLayout) != VK_SUCCESS) {
            return false;
        }
        pp.setLayout = setLayout;
        pp.pushBytes = pp.reflection.pushConstantBytes;
        VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, pp.pushBytes};
        VkPipelineLayoutCreateInfo pl{};
        pl.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
        pl.setLayoutCount = 1;
        pl.pSetLayouts = &setLayout;
        pl.pushConstantRangeCount = pp.pushBytes != 0u ? 1u : 0u;
        pl.pPushConstantRanges = &range;
        VkPipelineLayout layout = VK_NULL_HANDLE;
        if (vkCreatePipelineLayout(vk, &pl, nullptr, &layout) != VK_SUCCESS) {
            return false;
        }
        pp.layout = layout;
        VkShaderModuleCreateInfo mi{};
        mi.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        mi.codeSize = kc.bytes;
        mi.pCode = kc.words;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(vk, &mi, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo ci{};
        ci.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        ci.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        ci.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        ci.stage.module = module;
        ci.stage.pName = "main";
        ci.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(vk, VK_NULL_HANDLE, 1, &ci, nullptr, &pipeline);
        vkDestroyShaderModule(vk, module, nullptr);
        if (result != VK_SUCCESS) {
            return false;
        }
        pp.pipeline = pipeline;
    }
    VkDescriptorPoolSize sizes[8]{};
    u32 sizeCount = 0;
    for (u32 t = 0; t < 8u; ++t) {
        if (poolCounts[t] != 0u) {
            sizes[sizeCount++] = VkDescriptorPoolSize{static_cast<VkDescriptorType>(t), poolCounts[t]};
        }
    }
    VkDescriptorPoolCreateInfo pi{};
    pi.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
    pi.maxSets = setCount;
    pi.poolSizeCount = sizeCount;
    pi.pPoolSizes = sizes;
    VkDescriptorPool pool = VK_NULL_HANDLE;
    if (vkCreateDescriptorPool(vk, &pi, nullptr, &pool) != VK_SUCCESS) {
        return false;
    }
    m_pool = pool;
    for (u32 p = 0; p < kFgPassCount; ++p) {
        PassPipeline& pp = m_passes[p];
        if (pp.pipeline == nullptr) {
            continue;
        }
        for (u32 o = 0; o < pp.occurrences; ++o) {
            for (u32 s = 0; s < m_desc.framesInFlight; ++s) {
                VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(pp.setLayout);
                VkDescriptorSetAllocateInfo ai{};
                ai.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;
                ai.descriptorPool = pool;
                ai.descriptorSetCount = 1;
                ai.pSetLayouts = &setLayout;
                VkDescriptorSet set = VK_NULL_HANDLE;
                if (vkAllocateDescriptorSets(vk, &ai, &set) != VK_SUCCESS) {
                    return false;
                }
                pp.sets[o][s] = set;
            }
        }
    }
    return true;
#else
    return false;
#endif
}

void FrameGenGpu::destroyPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    const VkDevice vk = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pool != nullptr) {
        vkDestroyDescriptorPool(vk, static_cast<VkDescriptorPool>(m_pool), nullptr);
    }
    for (PassPipeline& pp : m_passes) {
        if (pp.pipeline != nullptr) {
            vkDestroyPipeline(vk, static_cast<VkPipeline>(pp.pipeline), nullptr);
        }
        if (pp.layout != nullptr) {
            vkDestroyPipelineLayout(vk, static_cast<VkPipelineLayout>(pp.layout), nullptr);
        }
        if (pp.setLayout != nullptr) {
            vkDestroyDescriptorSetLayout(vk, static_cast<VkDescriptorSetLayout>(pp.setLayout), nullptr);
        }
        pp = PassPipeline{};
    }
    for (void*& s : m_samplers) {
        if (s != nullptr) {
            vkDestroySampler(vk, static_cast<VkSampler>(s), nullptr);
        }
        s = nullptr;
    }
#endif
    m_pool = nullptr;
}

bool FrameGenGpu::createResources() {
#if defined(FUSE_VULKAN_BACKEND)
    const FgSizes& z = m_host.sizes;
    const u32 rw = z.maxRenderW, rh = z.maxRenderH, dw = z.displayW, dh = z.displayH;
    struct Spec {
        u32 slot, format, w, h, mips;
        const char* name;
    };
    Spec specs[kFgImageCount] = {
        {kSlotInputDepth, kR32Sfloat, rw, rh, 1, "fg.input_depth"},
        {kSlotInputMotion, kR32G32Sfloat, rw, rh, 1, "fg.input_motion"},
        {kSlotDilatedDepth, kR32Sfloat, rw, rh, 1, "fg.dilated_depth"},
        {kSlotDilatedMotion, kR16G16Sfloat, rw, rh, 1, "fg.dilated_motion"},
        {kSlotReconPrevDepth, kR32Uint, rw, rh, 1, "fg.reconstructed_depth_previous_frame"},
        {kSlotReconInterpDepth, kR32Uint, rw, rh, 1, "fg.reconstructed_depth_interpolated_frame"},
        {kSlotGameMvX, kR32Uint, rw, rh, 1, "fg.game_motion_vector_field_x"},
        {kSlotGameMvY, kR32Uint, rw, rh, 1, "fg.game_motion_vector_field_y"},
        {kSlotOfMvX, kR32Uint, rw, rh, 1, "fg.optical_flow_motion_vector_field_x"},
        {kSlotOfMvY, kR32Uint, rw, rh, 1, "fg.optical_flow_motion_vector_field_y"},
        {kSlotDisocclusion, kR8G8Unorm, rw, rh, 1, "fg.disocclusion_mask"},
        {kSlotInpaintingPyramid, kR16G16B16A16Sfloat, z.pyramidW, z.pyramidH, z.pyramidMips, "fg.inpainting_pyramid"},
        {kSlotPreviousSource, m_desc.sourceFormat, dw, dh, 1, "fg.previous_interpolation_source"},
        {kSlotDistortion, kR8G8Unorm, 1, 1, 1, "fg.default_distortion_field"},
        {kSlotOutput, kR16G16B16A16Sfloat, dw, dh, 1, "fg.output"},
        {kSlotPresentInterpolated, kR16G16B16A16Sfloat, dw, dh, 1, "fg.present_interpolated"},
        {kSlotPresentReal, kR16G16B16A16Sfloat, dw, dh, 1, "fg.present_real"},
    };
    u32 count = kSlotOfInput1;
    for (u32 l = 0; l < kFgOfLevels; ++l) {
        specs[count++] = Spec{kSlotOfInput1 + l, kR8Uint, std::max(z.ofInputW[l], 1u), std::max(z.ofInputH[l], 1u), 1, "fg.of.input1"};
    }
    for (u32 l = 0; l < kFgOfLevels; ++l) {
        specs[count++] = Spec{kSlotOfInput2 + l, kR8Uint, std::max(z.ofInputW[l], 1u), std::max(z.ofInputH[l], 1u), 1, "fg.of.input2"};
    }
    for (u32 l = 0; l < kFgOfLevels; ++l) {
        specs[count++] = Spec{kSlotOfFlow1 + l, kR16G16Sint, z.ofW[l], z.ofH[l], 1, "fg.of.flow1"};
    }
    for (u32 l = 0; l < kFgOfLevels; ++l) {
        specs[count++] = Spec{kSlotOfFlow2 + l, kR16G16Sint, z.ofW[l], z.ofH[l], 1, "fg.of.flow2"};
    }
    specs[count++] = Spec{kSlotOfScdHistogram, kR32Uint, 256u * 9u, 1, 1, "fg.of.scd_histogram"};
    specs[count++] = Spec{kSlotOfScdPreviousHistogram, kR32Sfloat, 256u * 9u, 1, 1, "fg.of.scd_previous_histogram"};
    specs[count++] = Spec{kSlotOfScdTemp, kR32Uint, 3, 1, 1, "fg.of.scd_temp"};
    specs[count++] = Spec{kSlotOfVector, kR16G16Sint, z.ofW[0], z.ofH[0], 1, "fg.of.vector"};
    specs[count++] = Spec{kSlotOfScdOutput, kR32Uint, 3, 1, 1, "fg.of.scd_output"};
    if (count != kFgImageCount) {
        return false;
    }
    bool ok = true;
    for (const Spec& s : specs) {
        if (!ok) {
            break;
        }
        Image& img = m_images[s.slot];
        TextureDesc d{};
        d.width = s.w;
        d.height = s.h;
        d.mipLevels = s.mips;
        d.format = static_cast<GpuFormat>(s.format);
        u32 usage = static_cast<u32>(ImageUsage::Sampled) | static_cast<u32>(ImageUsage::TransferDst) |
                    static_cast<u32>(ImageUsage::TransferSrc);
        if (s.slot != kSlotPreviousSource) {
            usage |= static_cast<u32>(ImageUsage::Storage);
        }
        d.usage = static_cast<ImageUsage>(usage);
        d.name = s.name;
        ok = m_desc.allocator->createImage(d, img.tex);
        img.format = s.format;
        img.width = s.w;
        img.height = s.h;
        img.mips = s.mips;
        img.name = s.name;
    }
    if (ok) {
        const VkDevice vk = static_cast<VkDevice>(m_desc.device->nativeHandle());
        const Image& pyr = m_images[kSlotInpaintingPyramid];
        for (u32 m = 0; m < kPyramidViews && ok; ++m) {
            VkImageViewCreateInfo vi{};
            vi.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO;
            vi.image = static_cast<VkImage>(pyr.tex.image);
            vi.viewType = VK_IMAGE_VIEW_TYPE_2D;
            vi.format = static_cast<VkFormat>(pyr.format);
            vi.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, std::min(m, pyr.mips - 1u), 1, 0, 1};
            VkImageView view = VK_NULL_HANDLE;
            ok = vkCreateImageView(vk, &vi, nullptr, &view) == VK_SUCCESS;
            m_pyramidViews[m] = view;
        }
    }
    if (ok) {
        BufferDesc b{};
        b.size = 8u;
        b.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::TransferDst) |
                                           static_cast<u32>(BufferUsage::TransferSrc));
        b.memoryUsage = MemoryUsage::GpuOnly;
        b.name = "fg.counters";
        ok = m_desc.allocator->createBuffer(b, m_counters);
    }
    m_cleared = false;
    return ok;
#else
    return false;
#endif
}

void FrameGenGpu::destroyResources() {
#if defined(FUSE_VULKAN_BACKEND)
    const VkDevice vk = m_desc.device != nullptr ? static_cast<VkDevice>(m_desc.device->nativeHandle()) : VK_NULL_HANDLE;
    for (void*& v : m_pyramidViews) {
        if (v != nullptr && vk != VK_NULL_HANDLE) {
            vkDestroyImageView(vk, static_cast<VkImageView>(v), nullptr);
        }
        v = nullptr;
    }
#endif
    for (Image& img : m_images) {
        if (img.tex.image != nullptr) {
            m_desc.allocator->destroyImage(img.tex);
        }
        img = Image{};
    }
    if (m_counters.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_counters);
    }
    m_counters = Buffer{};
    m_countersQueue = rg::kNoQueue;
    m_cleared = false;
}

bool FrameGenGpu::beginFrame(u64 frameSerial, const FgGpuFrameDesc& frame) {
    m_begun = false;
    m_stats.passes = 0;
    m_stats.clears = 0;
    if (!m_initialized) {
        return false;
    }
    FgFrameParams p{};
    p.renderW = frame.renderWidth;
    p.renderH = frame.renderHeight;
    p.jitter_px = frame.jitter_px;
    p.near_plane = frame.near_plane;
    p.far_plane = frame.far_plane;
    p.vertical_fov_rad = frame.vertical_fov_rad;
    p.view_space_to_meters = frame.view_space_to_meters;
    p.frame_time_ms = frame.frame_time_ms;
    p.reset = frame.reset || m_forceReset;
    p.frame_id = frame.frame_id;
    if (!fg_setup_frame(m_host, p, m_setup)) {
        return false;
    }
    m_forceReset = false;
    m_frame = frame;
    m_slot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    m_slotOffset = static_cast<u64>(m_slot) * kFgCbSlotBytes;
    u8* base = static_cast<u8*>(m_ring.mapped) + m_slotOffset;
    std::memcpy(base + fg_cb_offset(FgCb::Fi), &m_setup.fi, sizeof(m_setup.fi));
    std::memcpy(base + fg_cb_offset(FgCb::IpRender), &m_setup.ipRender, sizeof(m_setup.ipRender));
    std::memcpy(base + fg_cb_offset(FgCb::IpDisplay), &m_setup.ipDisplay, sizeof(m_setup.ipDisplay));
    std::memcpy(base + fg_cb_offset(FgCb::OfSpd), &m_setup.ofSpd, sizeof(m_setup.ofSpd));
    std::memcpy(base + fg_cb_offset(FgCb::OfBase), &m_setup.ofBase, sizeof(m_setup.ofBase));
    for (u32 l = 0; l < kFgOfLevels; ++l) {
        std::memcpy(base + fg_cb_offset(FgCb::OfLevel0, l), &m_setup.ofLevel[l], sizeof(m_setup.ofLevel[l]));
    }
    m_stats.fiReset = m_setup.fiReset;
    m_stats.ofReset = m_setup.ofReset;
    ++m_stats.frames;
    m_begun = true;
    return true;
}

FgGraphRefs FrameGenGpu::importInto(rg::Graph& graph) {
    FgGraphRefs refs{};
    if (!m_initialized) {
        return refs;
    }
    for (u32 i = 0; i < kFgImageCount; ++i) {
        Image& img = m_images[i];
        if (img.tex.image == nullptr) {
            continue;
        }
        rg::ImportedImage ii{};
        ii.image = img.tex.image;
        ii.view = img.tex.view;
        ii.format = img.format;
        ii.width = img.width;
        ii.height = img.height;
        ii.mipLevels = img.mips;
        ii.initialLayout = img.layout;
        ii.initialQueue = img.queue;
        ii.finalLayout = 1u; // VK_IMAGE_LAYOUT_GENERAL: every mip ends in one layout (the tracker covers the image)
        ii.layoutTracker = &img.layout;
        ii.queueTracker = &img.queue;
        ii.name = img.name;
        refs.images[i] = graph.importImage(ii);
    }
    refs.counters = graph.importBuffer(rg::ImportedBuffer{m_counters.handle, m_counters.desc.size, m_countersQueue, &m_countersQueue, "fg.counters"});
    refs.interpolated = refs.images[kSlotOutput];
    refs.presentInterpolated = refs.images[kSlotPresentInterpolated];
    refs.presentReal = refs.images[kSlotPresentReal];
    return refs;
}

u16 FrameGenGpu::slotFor(const FgDispatch& d, const FgBindingTarget& t) const {
    switch (t.resource) {
    case FgResource::SourceDepth: return kSlotSourceDepth;
    case FgResource::SourceMotion: return kSlotSourceMotion;
    case FgResource::InputDepth: return kSlotInputDepth;
    case FgResource::InputMotion: return kSlotInputMotion;
    case FgResource::CurrentSource: return kSlotCurrentSource;
    case FgResource::PreviousSource: return kSlotPreviousSource;
    case FgResource::DilatedDepth: return kSlotDilatedDepth;
    case FgResource::DilatedMotion: return kSlotDilatedMotion;
    case FgResource::ReconPrevDepth: return kSlotReconPrevDepth;
    case FgResource::ReconInterpDepth: return kSlotReconInterpDepth;
    case FgResource::DisocclusionMask: return kSlotDisocclusion;
    case FgResource::GameMvX: return kSlotGameMvX;
    case FgResource::GameMvY: return kSlotGameMvY;
    case FgResource::OfMvX: return kSlotOfMvX;
    case FgResource::OfMvY: return kSlotOfMvY;
    case FgResource::OpticalFlowVector: return kSlotOfVector;
    case FgResource::OpticalFlowScd: return kSlotOfScdOutput;
    case FgResource::Output: return kSlotOutput;
    case FgResource::InpaintingPyramid: return kSlotInpaintingPyramid;
    case FgResource::Counters: return kSlotCounters;
    case FgResource::DistortionField: return kSlotDistortion;
    case FgResource::OfInput: return d.ofInput;
    case FgResource::OfInputLevel: return d.ofInputLevelBase == kSlotNone ? static_cast<u16>(kSlotNone) : static_cast<u16>(d.ofInputLevelBase + t.mip);
    case FgResource::OfPreviousInput: return d.ofPreviousInput;
    case FgResource::OfFlow: return d.ofFlow;
    case FgResource::OfFlowSrv: return d.ofFlowSrv;
    case FgResource::OfFlowPrevious: return d.ofFlowPrevious;
    case FgResource::OfFlowNextLevel: return d.ofFlowNextLevel;
    case FgResource::OfScdHistogram: return kSlotOfScdHistogram;
    case FgResource::OfScdPreviousHistogram: return kSlotOfScdPreviousHistogram;
    case FgResource::OfScdTemp: return kSlotOfScdTemp;
    case FgResource::UiInput: return m_inputs.ui.valid() ? static_cast<u16>(kSlotUi) : d.compositeSource;
    case FgResource::CompositeSource: return d.compositeSource;
    case FgResource::CompositeTarget: return d.compositeTarget;
    default: return kSlotNone;
    }
}

rg::TextureRef FrameGenGpu::textureFor(u16 slot) const {
    if (slot < kFgImageCount) {
        return m_refs.images[slot];
    }
    if (slot == kSlotCurrentSource) {
        return m_inputs.source;
    }
    if (slot == kSlotUi) {
        return m_inputs.ui;
    }
    return rg::TextureRef{};
}

rg::BufferRef FrameGenGpu::bufferFor(u16 slot) const {
    switch (slot) {
    case kSlotCounters: return m_refs.counters;
    case kSlotSourceDepth: return m_inputs.depth;
    case kSlotSourceMotion: return m_inputs.motion;
    default: return rg::BufferRef{};
    }
}

bool FrameGenGpu::boundAsStorage(const PassPipeline& pp, const FgDispatch& d, u16 slot) const {
    for (u32 i = 0; i < pp.bindingCount; ++i) {
        const FgBindingTarget& t = pp.bindings[i].target;
        if (t.kind == FgBindingKind::Storage && slotFor(d, t) == slot) {
            return true;
        }
    }
    return false;
}

void FrameGenGpu::addPasses(rg::Graph& graph, const FgGraphRefs& refs, const FgGpuInputs& inputs) {
    if (!m_initialized || !m_begun || !inputs.source.valid() || !inputs.depth.valid() || !inputs.motion.valid() ||
        !refs.presentReal.valid() || !refs.counters.valid()) {
        return;
    }
    m_begun = false;
    m_inputs = inputs;
    m_refs = refs;

    // Clears (the SDK's clear jobs; first use: every image + the counters, deterministic history).
    ClearRecord& c = m_clear;
    c = ClearRecord{};
    c.self = this;
    auto clear = [&](u32 slot) {
        for (u32 i = 0; i < c.count; ++i) {
            if (c.refs[i].id == refs.images[slot].id) {
                return;
            }
        }
        c.refs[c.count++] = refs.images[slot];
    };
    if (!m_cleared) {
        for (u32 i = 0; i < kFgImageCount; ++i) {
            clear(i);
        }
        c.counters = true;
        m_cleared = true;
    }
    clear(kSlotReconPrevDepth); // ffxFrameInterpolationPrepare: "Clear Reconstructed Previous Nearest Depth"
    if (!m_setup.fiReset) {
        clear(kSlotReconInterpDepth); // "Clear Reconstructed Depth Interpolated Frame"
    }
    if (m_setup.ofReset) {
        clear(kSlotOfScdTemp);
        clear(kSlotOfScdOutput);
        clear(kSlotOfScdHistogram);
        clear(kSlotOfScdPreviousHistogram);
        for (u32 l = 0; l < kFgOfLevels; ++l) {
            clear(kSlotOfInput1 + l);
            clear(kSlotOfInput2 + l);
        }
    }
    {
        rg::PassBuilder pass = graph.addPass("fg.clear", &FrameGenGpu::recordClear, &m_clear);
        for (u32 i = 0; i < c.count; ++i) {
            pass.use(c.refs[i], rg::Access::TransferDst);
        }
        if (c.counters) {
            pass.use(refs.counters, rg::Access::TransferDst, rg::BufferRange{0, 8u});
        }
    }
    m_stats.clears = c.count;

    u32 occurrence[kFgPassCount] = {};
    for (u32 i = 0; i < m_setup.dispatchCount; ++i) {
        const u32 p = static_cast<u32>(m_setup.dispatches[i].pass);
        addDispatch(graph, i, occurrence[p]++);
    }
    // Store the current source as the next frame's previous interpolation source (the SDK's copy job).
    m_copy.self = this;
    graph.addPass("fg.copy_source", &FrameGenGpu::recordCopy, &m_copy)
        .use(inputs.source, rg::Access::TransferSrc)
        .use(refs.images[kSlotPreviousSource], rg::Access::TransferDst);
}

void FrameGenGpu::addDispatch(rg::Graph& graph, u32 index, u32 occurrence) {
    const FgDispatch& d = m_setup.dispatches[index];
    const PassPipeline& pp = m_passes[static_cast<u32>(d.pass)];
    DispatchRecord& rec = m_records[index];
    rec.self = this;
    rec.index = index;
    rec.occurrence = std::min(occurrence, pp.occurrences - 1u);
    rg::PassBuilder b = graph.addPass(fg_pass_name(d.pass), &FrameGenGpu::recordDispatch, &rec);
    u16 seen[kMaxBindings];
    u32 seenCount = 0;
    const u64 rn = static_cast<u64>(m_frame.renderWidth) * m_frame.renderHeight;
    for (u32 i = 0; i < pp.bindingCount; ++i) {
        const FgBindingTarget& t = pp.bindings[i].target;
        if (t.kind == FgBindingKind::Uniform || t.kind == FgBindingKind::Sampler) {
            continue;
        }
        const u16 slot = slotFor(d, t);
        bool dup = false;
        for (u32 k = 0; k < seenCount; ++k) {
            dup = dup || seen[k] == slot;
        }
        if (dup || slot == kSlotNone) {
            continue;
        }
        seen[seenCount++] = slot;
        if (t.kind == FgBindingKind::StorageBuffer) {
            const rg::BufferRef ref = bufferFor(slot);
            if (slot == kSlotCounters) {
                b.use(ref, rg::Access::StorageReadWrite, rg::BufferRange{0, 8u}, rg::kStageCompute);
            } else {
                b.use(ref, rg::Access::StorageRead, rg::BufferRange{0, rn * (slot == kSlotSourceDepth ? 4u : 8u)}, rg::kStageCompute);
            }
            continue;
        }
        const bool storage = t.kind == FgBindingKind::Storage || boundAsStorage(pp, d, slot);
        b.use(textureFor(slot), storage ? rg::Access::StorageReadWrite : rg::Access::SampledRead, {}, rg::kStageCompute);
    }
    ++m_stats.passes;
}

void FrameGenGpu::recordClear(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const ClearRecord& c = *static_cast<const ClearRecord*>(user);
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    for (u32 i = 0; i < c.count; ++i) {
        // Reconstructed depths: the inverted-depth clear value 0 (0 bits); everything else 0.
        const VkClearColorValue value{};
        const VkImageSubresourceRange range{VK_IMAGE_ASPECT_COLOR_BIT, 0, VK_REMAINING_MIP_LEVELS, 0, 1};
        vkCmdClearColorImage(cmd, static_cast<VkImage>(context.image(c.refs[i])), VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, &value, 1,
                             &range);
    }
    if (c.counters) {
        vkCmdFillBuffer(cmd, static_cast<VkBuffer>(context.buffer(c.self->m_refs.counters)), 0, 8u, 0u);
    }
#else
    (void)context;
    (void)user;
#endif
}

void FrameGenGpu::recordCopy(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const FrameGenGpu& self = *static_cast<const CopyRecord*>(user)->self;
    VkImageCopy region{};
    region.srcSubresource = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1};
    region.dstSubresource = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1};
    region.extent = {self.m_host.sizes.displayW, self.m_host.sizes.displayH, 1};
    vkCmdCopyImage(static_cast<VkCommandBuffer>(context.commandBuffer), static_cast<VkImage>(context.image(self.m_inputs.source)),
                   VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, static_cast<VkImage>(context.image(self.m_refs.images[kSlotPreviousSource])),
                   VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1, &region);
#else
    (void)context;
    (void)user;
#endif
}

void FrameGenGpu::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const DispatchRecord& rec = *static_cast<const DispatchRecord*>(user);
    const FrameGenGpu& self = *rec.self;
    const FgDispatch& d = self.m_setup.dispatches[rec.index];
    const PassPipeline& pp = self.m_passes[static_cast<u32>(d.pass)];
    const VkDevice vk = static_cast<VkDevice>(self.m_desc.device->nativeHandle());
    VkDescriptorSet set = static_cast<VkDescriptorSet>(pp.sets[rec.occurrence][self.m_slot]);
    VkWriteDescriptorSet writes[kMaxBindings]{};
    VkDescriptorImageInfo images[kMaxBindings]{};
    VkDescriptorBufferInfo buffers[kMaxBindings]{};
    u32 count = 0;
    const u64 rn = static_cast<u64>(self.m_frame.renderWidth) * self.m_frame.renderHeight;
    const VkBuffer ring = static_cast<VkBuffer>(self.m_ring.handle);
    for (u32 i = 0; i < pp.bindingCount; ++i) {
        const PassBinding& pb = pp.bindings[i];
        const FgBindingTarget& t = pb.target;
        if (t.kind == FgBindingKind::Sampler) {
            continue; // immutable
        }
        VkWriteDescriptorSet& w = writes[count];
        w.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
        w.dstSet = set;
        w.dstBinding = pb.binding;
        w.descriptorCount = 1;
        w.descriptorType = static_cast<VkDescriptorType>(pb.descriptorType);
        if (t.kind == FgBindingKind::Uniform) {
            u64 offset = fg_cb_offset(FgCb::Fi);
            u64 size = sizeof(FgFiConstants);
            if (t.resource == FgResource::ConstantsInpaintingPyramid) {
                offset = fg_cb_offset(d.cbIp);
                size = sizeof(FgInpaintingPyramidConstants);
            } else if (t.resource == FgResource::ConstantsOf) {
                offset = fg_cb_offset(d.cbOf, d.ofLevel);
                size = sizeof(FgOfConstants);
            } else if (t.resource == FgResource::ConstantsOfSpd) {
                offset = fg_cb_offset(FgCb::OfSpd);
                size = sizeof(FgOfSpdConstants);
            }
            buffers[count] = VkDescriptorBufferInfo{ring, self.m_slotOffset + offset, size};
            w.pBufferInfo = &buffers[count];
        } else if (t.kind == FgBindingKind::StorageBuffer) {
            const u16 slot = self.slotFor(d, t);
            const u64 size = slot == kSlotCounters ? 8u : rn * (slot == kSlotSourceDepth ? 4u : 8u);
            buffers[count] = VkDescriptorBufferInfo{static_cast<VkBuffer>(context.buffer(self.bufferFor(slot))), 0, size};
            w.pBufferInfo = &buffers[count];
        } else {
            const u16 slot = self.slotFor(d, t);
            const bool storage = t.kind == FgBindingKind::Storage;
            VkImageView view = VK_NULL_HANDLE;
            if (slot == kSlotInpaintingPyramid && storage) {
                view = static_cast<VkImageView>(self.m_pyramidViews[std::min<u32>(t.mip, kPyramidViews - 1u)]);
            } else {
                view = static_cast<VkImageView>(context.imageView(self.textureFor(slot)));
            }
            // A sampled binding of an image the same dispatch also writes is in GENERAL (declared StorageReadWrite).
            const bool general = storage || self.boundAsStorage(pp, d, slot);
            images[count] = VkDescriptorImageInfo{VK_NULL_HANDLE, view,
                                                  general ? VK_IMAGE_LAYOUT_GENERAL : VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL};
            w.pImageInfo = &images[count];
        }
        ++count;
    }
    vkUpdateDescriptorSets(vk, count, writes, 0, nullptr);
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(pp.pipeline));
    vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipelineLayout>(pp.layout), 0, 1, &set, 0, nullptr);
    if (d.pass == FgPass::Convert) {
        FgConvertPush push{};
        push.renderW = self.m_frame.renderWidth;
        push.renderH = self.m_frame.renderHeight;
        push.nearPlane = self.m_frame.near_plane;
        push.farPlane = self.m_frame.far_plane;
        vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(pp.layout), VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(push), &push);
    } else if (d.pass == FgPass::UiComposite) {
        FgCompositePush push{};
        push.width = self.m_host.sizes.displayW;
        push.height = self.m_host.sizes.displayH;
        push.hasUi = self.m_inputs.ui.valid() ? 1u : 0u;
        vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(pp.layout), VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(push), &push);
    }
    vkCmdDispatch(cmd, d.groups[0], d.groups[1], d.groups[2]);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::framegen
